insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids, pano_haov, search_note, pano_yaw, pano_pitch, pano_min_pitch) values ('92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'База и офис фирмы на Ташкентской', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-baza-wide2.jpg', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-baza-tashkentskaya.jpg', 'Ташкентская. Бывшая госбаза: бетонный забор, шлагбаум, будка КПП.', 59.8, 53.9, true, array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[], 240, 'Осмотр ничего не дал. Слишком чисто для конторы, где идёт торговля: пол вымыт, корзины пустые, на столах ни бумажки. Тут прибрались до вас. Спрашивайте людей.', null, null, null);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids, pano_haov, search_note, pano_yaw, pano_pitch, pano_min_pitch) values ('9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Дом Шмидтов в Горном Гиганте', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-shmidt-wide.jpg', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-dom-shmidtov.jpg', 'Горный Гигант. Частный сектор, улица немощёная. На калитке табличка «Продаётся».', 83.7, 32.5, true, array['f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba']::uuid[], 180, null, null, null, null);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids, pano_haov, search_note, pano_yaw, pano_pitch, pano_min_pitch) values ('ee497c59-0b63-50e6-91fc-8c67893c99ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Общежитие у Зелёного базара', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-obshaga-pano.jpg', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-obshchezhitie.jpg', 'Общежитие у Зелёного базара. На вахте бабушка в пуховом платке.', 59.4, 31.6, true, array['6a92b637-cb0c-5bf4-8495-f503839bf08c']::uuid[], null, null, 5, -5, null);
insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids, pano_haov, search_note, pano_yaw, pano_pitch, pano_min_pitch) values ('a2371d56-be63-59a7-81d4-f8745d432f5d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Квартира Фархада в микрорайоне «Орбита»', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-orbita-wide.jpg', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-orbita-cover.jpg', '«Орбита», юг города. Панельная девятиэтажка, четвёртый этаж.', 91.4, 73.4, true, array['cefb9e58-2cc4-5054-a43b-6216c7645217']::uuid[], 180, null, null, null, null);
