-- 3. Улики и показания
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('43eaf70c-177d-516a-9ab2-7aecc9633e33', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Протокол Медеуского РОВД: «грелся в машине, угорел»', 'МЕДЕУСКИЙ РОВД г. АЛМАТЫ

ПРОТОКОЛ
осмотра места происшествия
(выписка)

г. Алматы, 24 ноября 1996 г.
Осмотр начат в 10 час. 30 мин., окончен в 11 час. 40 мин.

Место осмотра: дачный участок гр. Сартакова И., Кок-Тобе.
Осмотр произведён по сообщению гр. Гринько В. (водитель), обнаружившего труп в 09 час. 40 мин.

В ходе осмотра установлено: в гараже находится легковой автомобиль иностранного производства тёмного цвета. На водительском сиденье труп мужчины, опознанный гр. Гринько В. как Сартаков И., 41 г. Ключ в замке зажигания, зажигание включено, топливный бак пуст. Ворота гаража на момент обнаружения закрыты. При наружном осмотре явных следов насилия не обнаружено.
Со слов соседей, в ночь с 23 на 24.11 в районе отключалась электроэнергия, котёл в доме не работал.

Вывод: гр. Сартаков И., находясь в автомобиле с работающим двигателем в закрытом гараже с целью обогрева во время отключения электроэнергии, отравился выхлопными газами. Признаков криминального характера не усматривается.

Приложение: фототаблица на 6 л.

Ст. оперуполномоченный
ст. лейтенант милиции          (подпись неразборчива)

Резолюция от руки: «Отказать в возбуждении уг. дела. Тело — родственникам». (подпись)', null, true, null, null, true, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('e34a96b0-5d0e-5414-9ef3-048071ef84ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тело Сартакова в морге: экспертиза не назначена', 'БЮРО СМЭ г. АЛМАТЫ
Журнал приёма (выписка)

24.11.96, 14:20. Сартаков И., 41 г. Доставлен из Медеуского РОВД. Основание: «для хранения до выдачи родственникам». Судебно-медицинское исследование: — (прочерк).

Поверх записи наискось, синим карандашом, рукой начальника следственного отдела ГУВД: «Кану. Вскрыть. Срочно. 25.11».

Холодный стол. Тело под простынёй, бирка на щиколотке.
Мужчина за сорок. Руки ухоженные. Щетина. Дорогие часы: РОВД их описал, а снять забыл.
Лицо одутловатое, с синевой. В белках глаз мелкие точечные кровоизлияния.
В протоколе РОВД об этом ни слова.', null, true, null, null, true, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('1ac01ab0-e8f1-5009-9640-d18dfa4f5e44', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер в арыке у ворот', 'Пейджер «Моторола». Чехол чёрный, кожаный, с клипсой.
Лежал в арыке у самых ворот дачи, под слоем мокрой листвы. Листва над ним не потревожена.
Корпус полон воды. Экран мёртвый, кнопки не отвечают. На задней крышке наклейка пейджинговой компании с номером абонента.
В двух шагах узкая калитка. Щеколда задвинута, на ней паутина с налипшими сухими листьями. Опергруппа РОВД ходила через большие ворота.
Машина в гараже. Пейджер у ворот. Почему не в машине?', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Пейджер', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('b4e6a60f-b233-543e-b3b1-ae0a1427b6a1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Следы обуви у въезда в гараж', 'Въезд в гараж, под свесом крыши. В слякоти следы обуви двух видов.
Первые: обувь женская, узкая, носок острый. Следы под подмёрзшей коркой.
Вторые: обувь мужская, крупного размера, протектор зимний, глубокий. Следы присыпаны тонким слоем снега.
Чьи раньше, чьи позже, видно на глаз: женские под коркой, мужские под снегом.', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Следы у гаража', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('34e1077a-bcc2-53ac-90e8-702d023d03c7', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Борозды у гаража и фототаблица РОВД', 'Там же, у въезда, со стороны водительской двери, две параллельные борозды. Длина около метра. Неглубокие, края рваные. Будто что-то тяжёлое волокли, а оно упиралось.

Фототаблица РОВД, снимки № 3 и № 4.
Сартаков за рулём. Голова откинута на подголовник. Руки лежат на коленях, ладонями вверх. Левая нога подвёрнута под сиденье. На педали её нет.
Ворот куртки поднят и застёгнут до подбородка.', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Борозды у гаража', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('a9b47e33-f5b4-57b9-9e16-1e41c38e7834', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Копоть на стене гаража', 'Задняя стена гаража, побелка. На высоте выхлопной трубы чёрное пятно копоти, веером вверх. Края жирные, сажа пачкает палец.
Двигатель здесь работал долго. Ворота были закрыты: на внутренней стороне створок тот же налёт.
В протоколе РОВД это пятно — главный довод: «грелся в машине, угорел».', '29196055-161c-5b4e-a38f-352cbf3e5032', true, 'Копоть на стене', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('e4e94374-000e-52e3-bb26-9bec42b1c55b', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Китайский АОН у телефона Валентины и блокнот', 'Определитель номера китайской сборки. Серая пластмассовая коробочка, красные цифры. Кнопки «память» и «стоп». Ставил Игорь: «чтобы мама знала, кто звонит».
Память на девяносто девять номеров. За воскресенье и понедельник набилось десятка три: больница, родня, школа, офис Игоря, соседи, телеграф.
Ниже, в субботе, один незнакомый. Первые цифры такие, какие бывают у частного сектора под горами. Время: суббота, 15:30.

Блокнот в клетку на тумбочке, карандаш на верёвочке. На открытой странице почерк учительницы:
«60» — обведено дважды.
«17:30 трамв. Ташкентская».
И тот же незнакомый номер. Подчёркнут.

Валентина Петровна, проходя мимо, закрывает блокнот. Говорит: звонков не было.', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', true, 'Телефон с АОН', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('5cdb3307-fe10-53c5-a365-6998256b7d7a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Конверт «на похороны» с пятью стодолларовыми купюрами', 'Белый почтовый конверт без марки. Стоял в серванте, у рюмок. Карандашом, рукой Валентины Петровны: «От Фархада — на похороны».
Внутри пять купюр по сто долларов США. Новые, «с маленькой головой».
Отдала сама, не дожидаясь вопроса, зачем он нужен.', null, true, null, null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('abc6fac8-abbd-5589-b6b5-958cd368e7fe', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фархад: перевязанная кисть', 'Рабочие заметки следователя (от руки).

Мамаджанов Фархад, 49 л.
Левая кисть забинтована. Бинт свежий, от запястья до костяшек. Повязка аккуратная, намотана своими руками.
На вопрос отмахнулся: «Казан. Плов делал, обжёгся. Ерунда, заживёт».', null, true, null, null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('4cc34317-760f-577c-b05f-e0374aee4f23', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал КПП базы: «Мамаджанов Ф., 16:10–16:40»', 'ЖУРНАЛ учёта посетителей и автотранспорта. КПП № 1.

(Страница за конец октября, выписка.)
28.10.96 | 09:15 | «КамАЗ» 45-17 | выгрузка, склад 3 | (подпись)
28.10.96 | 11:40 | Есенова Г. | в бухгалтерию | (подпись)
28.10.96 | 14:05 | «ГАЗель» | экспедитор Ли | (подпись)
28.10.96 | 16:10–16:40 | Мамаджанов Ф. | к Сартакову И. | пешком | (подпись)
28.10.96 | 17:20 | ЗИЛ | вывоз тары | (подпись)

(Последняя заполненная страница, выписка.)
23.11.96 | 11:30 | ЗИЛ | вывоз тары | (подпись)
23.11.96 | 17:55–19:10 | Ахметов Д. | ВАЗ-2109, белая | (подпись)
23.11.96 | 20:00 | заступил на смену Нуртазин Е. | (подпись)

Строчки как строчки. Таких здесь сотни. Почерк дневного дежурного ровный. В графе «цель визита» у Мамаджанова просто: «к Сартакову И.».', null, true, null, null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('4f67be3f-f5f7-5ab5-bb69-611053df3042', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Ксерокопии всех купюр выкупа из стола Данияра', 'Пачка листов формата А4. Ещё пахнут тонером.
На каждом листе восемь стодолларовых купюр, лицевой стороной. Серия и номер читаются без лупы. Листы пронумерованы карандашом в правом верхнем углу.
На последнем внизу мелкий аккуратный почерк: «23.11.96, 10:15. Итого 40 000. Д. А.».
Лежали в нижнем ящике стола Ахметова, под папкой «Договоры поставки — 1995».', null, true, null, null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('be5c249c-d25f-5239-865f-5aef2088bc61', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер охранного агентства на поясе Ерлана', 'Пейджер на клипсе, на ремне Нуртазина. Корпус потёрт. На обороте наклейка охранного агентства и номер абонента пейджинговой компании.
Память сообщений пуста: всё стёрто.
Вы просите показать пейджер. Ерлан долго возится с клипсой. Роняет пейджер на пол. Говорит, не глядя:
— Да там ничего нету. Служебное всё.', null, true, null, null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('c2c5ba62-e24e-523f-93bc-d8909b28e717', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Подвал Шмидтов: люк, матрас, верёвки, лампа, окурки', 'ПРОТОКОЛ осмотра (выписка)
Эксперт-криминалист Сеитова Г.

В полу кухни люк. Крышка деревянная, с железным кольцом. Ведёт в подвал глубиной около 2 м, спуск по приставной лестнице.
В подвале: матрас ватный, ветхий; обрезки бельевой верёвки, узлы затянуты; ведро эмалированное.
На кухне у люка лампа керосиновая «летучая мышь», стекло закопчено. С лампы и крышки люка изъяты следы пальцев рук.
В щелях пола у люка шесть окурков папирос. Гильзы смяты «гармошкой»: так обычно мнут «Беломор».', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Подвал', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('87af9a91-8540-5177-bdd6-3e156802fc75', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Шарф на матрасе в подвале', 'На матрасе, в изголовье, свёрнутый шарф. Мужской, серый, кашемировый, импортного производства. Мягкий, дорогой. Для этого подвала вещь чужая.
Свёрнут валиком, как подушка. На ткани пятна от сырости.', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Шарф', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('552b22f9-f4c6-5469-8d1c-56bde54906aa', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телефон в прихожей Шмидтов', 'Прихожая пустого дома. На стене телефонный аппарат, серый, дисковый. Гудок есть: линию не отключили.
Под диском бумажка, рукой хозяина: «48-27-15».
Тот самый номер. Он в памяти АОНа у Валентины Петровны: суббота, 15:30.
На трубке пыли нет. На полке рядом пыль в палец толщиной.', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', true, 'Телефон', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('46e78eb0-d057-5e5d-8a00-81457f8f3d20', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Вещи Олжаса: $3000 в куртке, куртка, ушанка, ботинки 45 размера', 'Протокол осмотра (выписка). Общежитие у Зелёного базара, комната 412, койка Бекенова О.

1. Куртка спортивная, импортная, синего цвета, на рукавах белые полосы. За подкладкой свёрток в газете «Вечерний Алматы». В свёртке тридцать купюр по 100 долларов США.
2. Шапка-ушанка, мех искусственный, чёрная.
3. Ботинки мужские зимние, 45 размер. Протектор на носке стёрт до гладкого.

Сосед по комнате, не поворачиваясь от стены:
— Он на мать копил. Говорил так.', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', true, 'Спортивная куртка', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('ed68230f-dcda-56e7-a77c-ecd7a4cc05a4', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал вахтёрши: Бекенов в субботу с 19:30 до утра в общежитии', 'ЖУРНАЛ входа-выхода проживающих (выписка)

23.11.96 (суббота)
19:30 — Бекенов О., к. 412 — вход.
(Записей о выходе Бекенова О. за 23.11 нет.)
24.11.96 (воскресенье)
08:50 — Бекенов О., к. 412 — выход.
Подпись вахтёра.', null, true, null, null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('00b31a8e-e1ee-5474-a323-177b43b153d3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зимние ботинки 43 размера с порезом на каблуке', 'Протокол обыска (выписка). Квартира гр. Мамаджанова Ф., мкр «Орбита».

В прихожей на расстеленной газете — ботинки мужские зимние, кожаные, чёрного цвета, 43 размер. На каблуке одного ботинка косой порез длиной около 1 см. Ботинки недавно вымыты: кожа в белёсых разводах, в шве у подошвы остатки грязи.
Других зимних ботинок в квартире не обнаружено. В шкафу летние туфли и домашние тапки.', 'a2371d56-be63-59a7-81d4-f8745d432f5d', true, 'Зимние ботинки', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('b322dfba-0cb0-52bc-9610-328a905bc004', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Расписка кредитора на бланке купонного инвестиционного фонда', 'Среди бумаг из пакета лист, сложенный вчетверо.
Сверху типографская шапка купонного инвестиционного приватизационного фонда: название, номер лицензии, адрес. Круглая печать фонда в углу смазана.
Ниже от руки, синей пастой:
«Я, нижеподписавшийся, получил от Мамаджанова Ф. доллары США в счёт долга и процентов по нему. Претензий по сроку не имею. 24.11.96».
Сумма вписана цифрами. Исправлена дважды. Подпись размашистая, с завитком. Расшифровки нет.
На обороте карандашом, другим почерком, столбик цифр. Перечёркнут.', 'a2371d56-be63-59a7-81d4-f8745d432f5d', true, 'Расписка', '[["2d1a03f4-be7f-5007-8fe1-71c12d498c29"]]'::jsonb, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('2d1a03f4-be7f-5007-8fe1-71c12d498c29', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тайник в мешке с рисом: доллары и расписки; доверенность Шмидтов в папке на полке', 'Протокол обыска (выписка). Квартира гр. Мамаджанова Ф., мкр «Орбита».

1. На кухне под столом мешок риса, около 25 кг, перевязан бечёвкой. В глубине мешка полиэтиленовый пакет. В пакете:
— доллары США купюрами по 100, пачками в банковских резинках;
— расписки гр. Мамаджанова Ф. в получении денег в долг, несколько листов. Суммы в долларах, «под проценты». Даты: лето и осень 1996 г.

2. В комнате, на полке над шкафом, канцелярская папка с завязками. Не спрятана. В папке бумаги по продаже дома. Среди них нотариальная доверенность: гр. Шмидт Г. уполномочивает гр. Мамаджанова Фархада продать принадлежащий ему жилой дом в частном секторе в Горном Гиганте, а до продажи распоряжаться им и пользоваться.

Рис высыпан на газеты. Понятые смотрят на рис.', 'a2371d56-be63-59a7-81d4-f8745d432f5d', true, 'Мешок с рисом', null, false, 'thing');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('54bf13bc-3525-5eec-9441-609d8ee21f59', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Заключение СМЭ: удушение, не угар', 'Заключение СМЭ: удушение, не угар; следы связывания; под ногтями чужая кровь.

АКТ судебно-медицинского исследования трупа гр. Сартакова И., 41 г. (выписка из выводов).
1. Смерть наступила 23.11.96 (суббота) около 22:00 от механической асфиксии вследствие сдавления шеи. Лицо одутловатое, синюшное, точечные кровоизлияния в соединительных оболочках глаз.
2. Признаков отравления окисью углерода не обнаружено. В автомобиль помещён после наступления смерти.
3. На запястьях слабо выраженные следы сдавления, характерные для связывания поверх одежды. Щетина около двух суток, признаки обезвоживания и голодания: не менее двух суток до смерти находился вне обычных условий.
4. Под ногтевыми пластинами обеих рук обнаружены следы крови группы II. Группа крови покойного — I.
Судмедэксперт Кан Ю. Н. (подпись). 25.11.96.', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('7ada2011-2720-5b69-8a9c-9291fdad70e9', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пейджер Игоря: последний сигнал в четверг', 'Пейджер Игоря: с вечера четверга ничего не принял, на сообщения никто не перезвонил.

Справка. По запросу следователя сообщаю: пейджер, изъятый из арыка у ворот дачи, после просушки и замены элемента питания включён. Последнее принятое сообщение в памяти аппарата — 21.11.96 (четверг), 17:35. Сообщений, принятых позже, нет.
Эксперт-криминалист ЭКО Сеитова Г. (подпись).

Справка. По запросу сообщаю: согласно журналу пейджинговой компании, с вечера 21.11.96 по 23.11.96 на номер абонента Сартакова И. передавались сообщения из офиса фирмы («СРОЧНО ПЕРЕЗВОНИ») и от Сартаковой В. П. Со слов сотрудников офиса, ответного звонка не поступало. Пейджер односторонний, факт прочтения сообщения оператором не фиксируется.
Оператор ИВЦ Абишев Р. (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('60950128-af31-513e-b8de-bb87b02332cc', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Трасология: следы у гаража', 'Трасология у гаража: мужские следы ночные, женские — дневные, раньше.

Заключение эксперта-криминалиста Сеитовой Г. (выводы).
1. Следы мужской зимней обуви, 43 размер, на каблуке косой порез около 1 см. Покрыты тонким слоем снега, выпавшего около 01:00 в воскресенье 24.11.96; оставлены ночью, до снегопада.
2. Следы женской обуви, 37 размер. Находятся под подмёрзшей коркой слякоти; оставлены ранее, в светлое время суток.
3. Две параллельные борозды со стороны водительской двери — следы волочения: тело переносили, ноги волочились по земле.
Эксперт (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('c4c95f03-86b0-5820-b9f4-736453e2dbef', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Виктор: «по четвергам он ездил один»', 'Виктор: по четвергам Игорь ездил на дачу один; у базы стояла «Волга» с одной фарой.

Из объяснения гр. Гринько В.: по четвергам в 17:00 Сартаков отпускал водителя и уезжал на дачу один. Привычка появилась после развода, о ней знали в офисе и на КПП. В четверг за неделю до смерти Сартакова у ворот базы стояла белая «Волга» ГАЗ-24 с разбитой левой фарой; водитель курил и смотрел на ворота. Номер не запомнил. Водителя не знает.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('0a295d5f-e115-5c89-a26a-5992761304a0', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Виктор: ссора Игоря с Данияром', 'Виктор: Игорь кричал на Данияра «Месяц тебе, или сядешь».

Из объяснения гр. Гринько В.: в субботу 16.11.96, за пять дней до пропажи Сартакова, находясь в приёмной, слышал, как Сартаков кричал в кабинете на Ахметова: «Месяц тебе, или сядешь». Ахметов вышел из кабинета бледный. О чём шла речь, не знает.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('42ea83ef-f3ad-504f-99e0-da4ecb9fe57d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Алия: в пятницу гараж был пуст', 'Алия: в пятницу в 15:00 гараж был пуст; в субботу она была на дежурстве.

Из объяснения гр. Жумабаевой (Сартаковой) А.: в пятницу 22.11.96 около 15:00 открыла ворота и дом дачи своими старыми ключами (на одной связке), забрала папку документов о приватизации дачи для адвоката. Гараж был пуст, машины не было. В субботу 23.11.96 с 20:00 до 08:00 находилась на ночном дежурстве в городской больнице; в 23:10 давала наркоз при экстренной операции. Подтверждается журналом дежурств и протоколом операции с её подписью.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('b170d031-ba6c-5e70-829f-cbd96f761931', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Валентины: похищение и выкуп', 'Валентина признаётся: похищение, звонки, тайный выкуп.

Из протокола допроса свидетеля Сартаковой В. П.: в четверг 21.11.96 около 21:00 позвонили из таксофона, потребовали $60 000, пригрозили расправой над внучкой в случае обращения в милицию. В милицию не обращалась. Водителю Гринько сказала, что сын уехал в Бишкек. Вместе с Ахметовым Д. собрала $40 000. В субботу 23.11.96 в 15:30 позвонили повторно и назвали место; номер сохранился в памяти АОН. В субботу с 19:30 до 01:30 Ахметов находился у неё; ждали звонка, что сына отпустили.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('6d8d58c7-784b-5d25-9f9e-d6c55f6966ba', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фархад: «сидел при свечке»', 'Фархад среди пришедших с соболезнованием: «давно помирились»; в субботу «сидел при свечке».

Со слов гр. Мамаджанова Ф.: с Сартаковым И. давно помирились, зла не держал. В субботу вечером находился дома в мкр «Орбита» один: дочь Зарина с четверга у родственников в Ташкенте. «У нас свет отключили», сидел при свечке, никуда не выходил.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('ea60506a-dfdb-5176-a63a-2fd3c47f8b6e', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Данияра: выкуп и копии купюр', 'Данияр признаётся: выкуп из «чёрной» кассы, курьер на остановке, алиби.

Из протокола допроса гр. Ахметова Д.: о похищении знал с пятницы; по просьбе Сартаковой В. П. в милицию не обращался. $40 000 взял из неучтённой кассы фирмы и вернул туда ранее выведенные им средства. Перед передачей снял ксерокопии всех купюр. В 15:30, во время второго звонка, находился у Сартаковой В. П., номер на АОН видел сам; оттуда с пакетом поехал на остановку. В субботу в 17:30 оставил пакет под скамейкой на трамвайной остановке на ул. Ташкентской. В темноте видел только высокого молодого парня в спортивной куртке и ушанке, лица не разглядел. Оттуда в 17:55 заехал на базу, убрал ксерокопии в свой стол, в 19:10 выехал (журнал КПП). В 19:30 вернулся к Сартаковой В. П. и находился у неё до 01:30.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('009a36f7-b362-586d-8943-61cd46149c3c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Данияр: «Я тебя садиться не просил»', 'Данияр: в октябре Игорь отказал Фархаду в доле и унизил его.

Из протокола допроса гр. Ахметова Д.: 28.10.96 Мамаджанов Ф. пришёл на базу просить свою долю. Сартаков в присутствии Ахметова ответил: «Я тебя садиться не просил. Хочешь — иди завскладом». Мамаджанов ушёл молча. В 1994 г. Мамаджанов был осуждён за товар их общей фирмы, взял вину на себя, отбыл полтора года.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('9eedb06d-09c9-5fa6-b91f-46d7753f78b4', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Справка электросетей: Кок-Тобе', 'Справка электросетей: район Кок-Тобе в субботу обесточен с 19:00 до 02:00.

ДИСПЕТЧЕРСКАЯ СЛУЖБА РАЙОННЫХ ЭЛЕКТРОСЕТЕЙ
Справка. По запросу ГУВД о районе Кок-Тобе сообщаю: 23.11.96 с 19:00 до 02:00 24.11.96 потребители района Кок-Тобе отключены по графику ограничения потребления.
Диспетчер (подпись неразборчива). Печать.', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('64b699fc-69d6-5bc3-ab81-b5a48df561bd', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Справка электросетей: «Орбита»', 'Справка электросетей: в «Орбите» ни в пятницу, ни в субботу свет не отключали.

ДИСПЕТЧЕРСКАЯ СЛУЖБА РАЙОННЫХ ЭЛЕКТРОСЕТЕЙ
Справка. По отдельному запросу ГУВД сообщаю: в мкр «Орбита» 22.11.96 и 23.11.96 плановых и аварийных отключений потребителей не производилось.
23.11.96 с 19:00 до 02:00 24.11.96 по графику ограничения отключались потребители районов Кок-Тобе и Горный Гигант.
Диспетчер (подпись неразборчива). Печать.', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Адресное бюро: телефон Шмидта', 'Адресное бюро: номер из АОН — телефон Шмидта Г., выбывшего в ФРГ.

Справка. По запросу сообщаю: номер телефона, зафиксированный в памяти АОН 23.11.96 в 15:30, зарегистрирован на гр. Шмидта Г. Абонент выбыл на постоянное жительство в ФРГ. Адрес установки — частный сектор в Горном Гиганте. Со слов участкового инспектора, дом пустует и продаётся по доверенности. Телефон не отключён.
Оператор ИВЦ Абишев Р. (подпись).', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('27ae146a-a05c-5e7a-84a1-899c35e883e4', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Дактилоскопия: пальцы на люке и лампе', 'Дактилоскопия: пальцы на люке и лампе — Мамаджанова Ф.; его группа — II.

Справка. По результатам ручного сравнения с дактокартотекой сообщаю:
1. Следы пальцев рук с крышки люка подвала и с керосиновой лампы в доме Шмидта совпадают с дактокартой гр. Мамаджанова Фархада (судим в 1994 г., таможенное дело).
2. Второй набор следов с крышки люка по картотеке не значится (лицо, не имеющее судимости).
3. В учётном деле Мамаджанова Ф. имеется медицинская карта из колонии: группа крови II.
Оператор ИВЦ Абишев Р. (подпись).', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('f725c4c5-f254-5c01-b718-3531a957102a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Показания Тамары Шнайдер', 'Тамара: «Волга» Фархада у дома Шмидтов с 18:15 до ночи; покупателей не было; иномарка уехала без фар.

Из протокола допроса свидетеля Шнайдер Т. Ф.: дом Шмидтов продаёт Мамаджанов Фархад, он водил покупателей, свидетель знает его в лицо. В среду он сказал ей: «скоро въедут люди». В пятницу из трубы пустого дома шёл дым, под навесом стояла тёмная иномарка, печь топил высокий молодой парень. В субботу около 18:15 в свете единственной фары подъехала белая «Волга», из неё вышли Мамаджанов и высокий молодой парень; парень вскоре ушёл пешком. Больше в тот вечер никто не приезжал, покупателей не было. После отключения света на улице до ночи светилось только окно Шмидтов (керосиновая лампа). Около 23:20 со двора выехала иномарка с выключенными фарами; свидетель узнала её по звуку мотора. «Волга» простояла у калитки примерно до 01:30 и уехала по свежему снегу.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('c50332f2-fb14-5cff-9ea2-9581024ac2e3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Журнал пейджинга: «ЧЕТВЕРГ В СИЛЕ? Ф.»', 'Журнал пейджинговой компании: «ЧЕТВЕРГ В СИЛЕ? Ф.» на пейджер Ерлана.

Выписка из журнала операторов пейджинговой компании (по запросу ГУВД).
21.11.96, 16:30. Абонент: Нуртазин Е. Текст сообщения: «ЧЕТВЕРГ В СИЛЕ? Ф.».
Оператор (подпись). Выписка верна.', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('b229ab87-5e5b-5f61-8a7b-18c17718e4cf', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Ерлана', 'Ерлан признаётся: продал Фархаду «четверги» за списанный долг.

Из протокола допроса гр. Нуртазина Е.: в 1993 г. Мамаджанов Ф. дал ему $1500 на операцию матери; долг возвращён не был. В субботу 09.11.96, за две недели до пропажи Сартакова, в чайхане у Зелёного базара Мамаджанов предложил списать долг, если Нуртазин скажет, когда Сартаков ездит без водителя, — «поговорить по-мужски». Нуртазин сообщил про четверги. В четверг 21.11.96 получил сообщение на пейджер и подтвердил по телефону. О похищении не знал. В субботу с 20:00 до 08:00 находился на смене, ежечасно отзванивался на пульт агентства.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Профиль Бейсенова: похититель знаком жертве', 'Криминолог: заложника убивают после выкупа, когда боятся опознания.

Из консультации доцента Высшей школы МВД Бейсенова А.: в типичном случае заложника после получения выкупа отпускают; убивают, как правило, когда похититель опасается опознания, то есть жертва была с ним знакома. Инсценировку выполнил человек, знавший дачу и привычки Сартакова и рассчитывавший на молчание семьи. Круг лиц: друзья семьи, партнёры, бывшие супруги, охрана.', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('d91852b9-daca-5340-80c9-a13cffe680cc', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Деньги Олжаса — из выкупа', 'Сравнение купюр: $3000 Бекенова — из выкупа.

ПРОТОКОЛ сравнения (эксперт-криминалист Сеитова Г.): номера и серии тридцати купюр достоинством $100, изъятых у гр. Бекенова О., полностью совпадают с номерами на ксерокопиях купюр выкупа, представленных Ахметовым Д.
Эксперт (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('0146fe89-1029-5d65-87bb-f750dfe7ad2d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Олжаса: похищение', 'Олжас признаётся в похищении — и твердит, что «аке ни при чём».

Из протокола допроса подозреваемого Бекенова О.: в четверг вечером схватил Сартакова у ворот дачи; перегнал его машину во двор дома Шмидтов (водить умеет, водительского удостоверения не имеет); удерживал Сартакова в подвале. Звонил Сартаковой В. П. из таксофонов, в субботу — с телефона в доме Шмидтов, так как таксофон на остановке был сломан. В субботу забрал пакет с деньгами на остановке. Утверждает, что действовал один: «Аке ни при чём, я сам всё придумал». Считает, что утром Сартакова отпустили, тот уехал на своей машине на дачу и умер сам, от угара.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Очная ставка: «Я тебя узнал»', 'Очная ставка: Олжас передал Фархаду «я тебя узнал» — и был отослан.

Из протокола очной ставки между Бекеновым О. и Мамаджановым Ф. (кабинет следователя ГУВД): узнав, что Сартаков задушен около 22:00, а остаток выкупа обнаружен у Мамаджанова, Бекенов показал: с остановки к дому Шмидтов приехали вдвоём с Мамаджановым; кроме них, в доме находился только Сартаков. Около 18:15 передал Мамаджанову слова Сартакова: «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу». Со слов Бекенова, Сартаков узнал Мамаджанова через мешок на голове — по кашлю и запаху «Беломора». Около 18:45 Мамаджанов отправил Бекенова в общежитие, сказав, что утром отпустит Сартакова за городом.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('6fc41a46-a0eb-5890-9b26-3b19bcef490d', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Трасология: ботинки с порезом', 'Трасология: ботинки Мамаджанова оставили мужские следы у гаража.

Заключение эксперта-криминалиста Сеитовой Г.: следы мужской обуви у гаража дачи на Кок-Тобе оставлены ботинками, изъятыми при обыске в квартире гр. Мамаджанова Ф. Совпадают размер, рисунок протектора, порез на каблуке.
Эксперт (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('107fcb2c-e909-5f81-bba4-d218265227c5', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Доллары из тайника — из выкупа', 'Сравнение купюр: доллары из тайника Фархада — из выкупа.

ПРОТОКОЛ сравнения (эксперт-криминалист Сеитова Г.): номера и серии всех купюр, изъятых из мешка с рисом в квартире гр. Мамаджанова Ф., совпадают с ксерокопиями купюр выкупа.
Эксперт (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Освидетельствование: царапины от ногтей', 'Освидетельствование: под повязкой — царапины от ногтей, ожога нет; группа II.

ПРОТОКОЛ освидетельствования задержанного Мамаджанова Ф. (в присутствии понятых). Заключение судмедэксперта Кана Ю. Н.: на тыльной стороне левой кисти под повязкой — три параллельные царапины, причинённые ногтями человека. Давность четверо-шестеро суток, в стадии заживления; причинение вечером 23.11.96 не исключается. Следов ожога нет. Характерных следов когтей животного нет. Группа крови Мамаджанова Ф. — II (по медкарте колонии), совпадает с группой крови под ногтями Сартакова.
Судмедэксперт (подпись). Понятые (подписи).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('26a10711-a53c-5105-9ed4-190697869496', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Купюры из конверта — из выкупа', 'Сравнение купюр: конверт «на похороны» — из выкупа.

ПРОТОКОЛ сравнения (эксперт-криминалист Сеитова Г.): номера пяти купюр достоинством $100 из конверта, переданного Мамаджановым Ф. гр. Сартаковой В. П., совпадают с ксерокопиями купюр выкупа.
Эксперт (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('b177dd97-7391-5f5e-8308-72a1073516c2', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Группы крови подозреваемых', 'Группы крови фигурантов: II — у двоих из четверых.

Справка. По медицинским картам и учётным делам сообщаю группы крови:
Мамаджанов Ф. — II (медкарта колонии);
Ахметов Д. — II;
Нуртазин Е. — I (личное дело МВД);
Жумабаева А. — III.
Кровь под ногтями Сартакова — группа II.
Судмедэксперт Кан Ю. Н. (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('7a9bdd9a-4323-5342-a3bd-24301a6d6e88', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Трасология: обувь подозреваемых', 'Трасология: обувь проверенных фигурантов не совпадает со следами у гаража.

Заключение эксперта-криминалиста Сеитовой Г.:
Нуртазин Е. — форменные ботинки, 43 размер, протектор другого рисунка;
Ахметов Д. — изъята вся обувь 43 размера: импортные туфли с гладкой подошвой и зимние ботинки с протектором иного рисунка, без пореза;
Жумабаева А. — 37 размер.
Ни одна из изъятых пар мужских следов у гаража не оставила.
Эксперт (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('d8f33493-fc81-5e50-af40-37d9500040b6', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'ИЦ/ГАИ: машины подозреваемых', 'ИЦ/ГАИ: машины фигурантов — белые только у двоих.

Справка. По запросу, по данным ИЦ и ГАИ, сообщаю:
Мамаджанов Ф. — ГАЗ-24 «Волга», белая;
Ахметов Д. — ВАЗ-2109, белая (при осмотре фары целы);
Жумабаева А. — ЗАЗ «Таврия», красная;
Нуртазин Е. — личного транспорта нет, пользуется служебным УАЗ агентства.
Оператор ИВЦ Абишев Р. (подпись).', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Признание Фархада', 'Признание Фархада: решил убить, когда узнал, что Игорь его узнал.

Из протокола допроса обвиняемого Мамаджанова Ф.: Нуртазину списал долг за сведения о четвергах. Бекенову сказал, что никто не пострадает. Решение убить принял, когда Бекенов передал, что Сартаков его узнал. Задушил Сартакова один, тело отвёз на машине Сартакова на Кок-Тобе и оставил с работающим двигателем. С Кок-Тобе спустился пешком, внизу остановил частника; номер машины не помнит. Часть денег отдал кредитору.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('cefb9e58-2cc4-5054-a43b-6216c7645217', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Санкция прокурора на задержание', 'Санкция прокурора: задержание Мамаджанова Ф. и обыск в его квартире в «Орбите».

ПОСТАНОВЛЕНИЕ о задержании подозреваемого и производстве обыска (выписка).
Задержать Мамаджанова Фархада в порядке, предусмотренном УПК. Произвести обыск по месту его жительства: г. Алматы, мкр «Орбита».
В углу листа фиолетовыми чернилами: «Санкционирую». Прокурор (подпись). Гербовая печать.

Начальник отдела ставит подпись под прокурорской. Не садясь.
— Две независимые бумаги на одного человека. Прокурору хватило. Бери понятых, бери Сеитову. Его — сюда, в кабинет. И без самодеятельности: он никуда не бегал, значит, уверен в себе. Берите спокойно.', null, true, null, '[["27ae146a-a05c-5e7a-84a1-899c35e883e4", "f725c4c5-f254-5c01-b718-3531a957102a"], ["27ae146a-a05c-5e7a-84a1-899c35e883e4", "26a10711-a53c-5105-9ed4-190697869496"], ["f725c4c5-f254-5c01-b718-3531a957102a", "26a10711-a53c-5105-9ed4-190697869496"]]'::jsonb, true, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('6a92b637-cb0c-5bf4-8495-f503839bf08c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Адресное бюро: племянник Мамаджанова', 'Адресное бюро: племянник Мамаджанова — Бекенов Олжас, общежитие у Зелёного базара.

Справка. По запросу сообщаю: в учётном деле Мамаджанова Ф. (1994 г.), в анкете, в графе «родственники» указана двоюродная сестра — Бекенова, Талгарский район. По данным адресного бюро, в г. Алматы временно прописан Бекенов Олжас, 22 года, уроженец Талгарского района. Адрес: общежитие у Зелёного базара, комната 412.
Оператор ИВЦ Абишев Р. (подпись).', null, true, null, null, false, 'document');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('9281d556-d163-5537-a0e2-e4cd2e635ba5', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Экспертизы по Бекенову и Ахметову', 'Экспертизы по задержанному Бекенову: второй набор пальцев — его; царапин нет ни у него, ни у Ахметова.

Сводная справка (Сеитова Г., Кан Ю. Н., Абишев Р.).
1. Второй набор следов пальцев рук с крышки люка подвала Шмидтов оставлен Бекеновым О. С отпечатками Ахметова Д. (дактилоскопирован добровольно) не совпадает.
2. Группа крови Бекенова О. — II.
3. Кисти рук Бекенова О. и Ахметова Д. осмотрены: свежих повреждений нет.
4. По данным ГАИ, водительского удостоверения и транспорта у Бекенова О. нет; со слов Бекенова, водить умеет.
(подписи)', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('4e8b269e-8c91-5629-b60d-13930fa7e61e', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зоя Михайловна: «девятка» до ночи', 'Соседка Зоя Михайловна: «девятка» Данияра под окном до ночи, около 22:00 он курил на лестнице.

Из объяснения гр. Лукиной З. М. (соседка Сартаковой В. П. по лестничной площадке): белая ВАЗ-2109 Ахметова стояла под окнами дома с вечера субботы 23.11.96 до глубокой ночи. Около 22:00, «перед вторым „Временем“», Ахметов курил на лестничной площадке; свидетель вышла на запах дыма и сделала ему замечание. Окурки импортных сигарет — в банке у мусоропровода.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('06da149b-c92c-54fa-a5f5-b78ff87dbc92', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Хронология против версии о Данияре', 'Хронология: подготовка похищения старше ссоры Игоря с Данияром.

Сводная таблица дат по материалам дела:
09.11 (сб) — разговор в чайхане у Зелёного базара: наводчику предложено списать долг за сведения о четвергах (показания Нуртазина Е.);
14.11 (чт) — белая «Волга» с разбитой левой фарой у ворот базы (показания Гринько В.);
16.11 (сб) — Сартаков уличает Ахметова в выводе денег: «Месяц тебе, или сядешь» (показания Гринько В.);
21.11 (чт) — похищение.
Наводка и наблюдение за базой начаты ранее, чем возник конфликт Ахметова с Сартаковым.', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('7188cb7d-2261-5a9c-8f78-e603caa6b31a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фархад: «показывал дом покупателю»', 'Запасная версия Фархада: «показывал дом покупателю».

Со слов задержанного Мамаджанова Ф.: в субботу вечером заезжал в дом Шмидтов, показывал дом покупателю; сидели с керосиновой лампой, так как света не было. Покупатель уехал, затем уехал и он. Про свечку дома «перепутал»: свет в «Орбите», по его словам, отключали в пятницу. Имени покупателя не называет.', null, true, null, null, false, 'testimony');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('3772cdd6-1fe9-52d0-a268-3f82441220c7', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Осмотр машины Игоря: глина и чистый руль', 'Машина Игоря на стоянке РОВД: глина в колёсных арках, на руле ни одного отпечатка.

Справка. По результатам осмотра автомобиля Сартакова И. на стоянке Медеуского РОВД сообщаю: в колёсных арках налёт жёлтой глины, характерной для немощёных улиц частного сектора (такие улицы, в частности, в Горном Гиганте). Подъезд к даче на Кок-Тобе — асфальт и щебень. На рулевом колесе следов пальцев рук не выявлено, в том числе следов владельца: последним автомобилем управлял человек в перчатках.
Эксперт-криминалист ЭКО Сеитова Г. (подпись).', null, true, null, null, false, 'expertise');
insert into evidence (id, case_id, name, description, location_id, is_relevant, generic_category, requires_any, auto_grant, kind) values ('e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Валентина: расцарапанная рука Фархада', 'Валентина о Фархаде: конверт, расцарапанная рука, «Береги Дашу».

Из протокола дополнительного допроса свидетеля Сартаковой В. П.: в воскресенье 24.11.96 вечером Мамаджанов Ф. принёс конверт с деньгами «на похороны». На левой кисти у него были свежие царапины; на её вопрос ответил: «Собака на базаре». Уходя, в прихожей, наедине сказал ей: «Бандиты сейчас такие, Валентина-апа. Береги Дашу, никому ни слова». Тогда она приняла это за заботу.', null, true, null, null, false, 'testimony');
