insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пустая бутылка', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Бутылка из-под «Жигулёвского» под яблоней. Этикетка размокла, внутри прелые листья. Лежит тут с осени.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Детская варежка', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Красная вязаная варежка на штакетнике. Детская. Кто-то нашёл и надел на штакетину, чтобы хозяин заметил. С прошлой зимы висит.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Сломанный зонт', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Чёрный складной зонт у крыльца. Спицы вывернуты ветром. Бросили и забыли.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Детский велосипед', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Детский велосипед под клеёнкой. Цепь в ржавчине, шины спущены. С лета не трогали.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Мешок угля', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Мешок угольных брикетов на крыльце, початый. А котёл холодный, зола старая: в эти выходные дом не топили.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Канистра', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Красная канистра у стены гаража. Пустая, крышка завинчена, сверху пыль. Её давно не открывали.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Ветошь', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Куча промасленной ветоши и старая покрышка в углу гаража. Обычный гаражный хлам.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Масляное пятно', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Тёмное пятно на бетоне посреди гаража, старое, въевшееся. Машина годами стояла на одном месте и подтекала.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Калитка', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Узкая калитка рядом с воротами. Щеколда задвинута. На щеколде паутина, в ней сухие листья. Через калитку давно никто не ходил.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Портрет с лентой', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Портрет Игоря в рамке, чёрная лента наискосок. Снимок с документа, увеличенный в фотоателье. Пиджак, галстук, взгляд в объектив.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Рюмка с хлебом', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Рюмка водки, накрытая куском чёрного хлеба. Так положено: для покойного. Водка не тронута.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фотография', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Фото за стеклом серванта: девочка в школьной форме, белый фартук, банты. На обороте рукой Валентины Петровны: «Даша, 1 сентября 1996».');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зеркало', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Зеркало в прихожей завешено простынёй. Пока покойник не похоронен, так положено.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телеграммы', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Пачка телеграмм на подоконнике. Караганда, Москва, сослуживцы Игоря. «Скорбим вместе с вами». Все за воскресенье и понедельник.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телевизор', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Телевизор «Горизонт» на тумбе с кружевной салфеткой. Выключен. В доме траур.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Конверт', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Конверт в серванте, у рюмок. Подписан карандашом: «От Фархада — на похороны». Чужие деньги без спроса не берут: спросите хозяйку.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тарелки', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Тарелки на столе из разных сервизов: соседи несли кто что мог. К поминкам готовятся заранее, хотя тело ещё не отдали.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фикус', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Фикус в кадке у двери. Засох совсем, листья на полу. Поливать было некому: секретаршу Сартаков отпустил ещё летом.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Стулья', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Ряд стульев для посетителей в коридоре. Пустые. Сегодня приёма нет.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Вешалка', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Вешалка на стене в приёмной. Ни одного пальто: секретаршу отпустили ещё летом.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телефон секретаря', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Кнопочный телефон на пустом столе. Гудок есть. Рядом ни записной книжки, ни бумажки с номерами.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Урна', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Корзина для бумаг под столом. Пустая и чистая, будто её вымыли.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Сейф', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Зелёный сейф в кабинете Ахметова. Заперт. Ключ у самого Ахметова.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Папки', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Папки на полке подписаны по годам: 1993, 1994, 1995, 1996. Стоят ровно, корешок к корешку.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Ксерокс', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Ксерокс под матерчатым чехлом. Чехол чистый, без пыли: снимали недавно.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Календарь', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Японский календарь с «Тойотой Ленд Крузер». Подарок поставщиков. Листы не оторваны с весны.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Карта города', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Карта Алматы на стене. Ни флажков, ни пометок.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Часы', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Настенные часы. Идут точно, по радио сверены.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Грузовик', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'За окном «КамАЗ» с китайскими ящиками. Водитель ждёт разгрузки и курит в кабине.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Шлагбаум', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Шлагбаум и будка КПП за окном. В будке горит свет, там дежурит охрана.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Ковёр', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Ковёр на стене, красный, с узором. Выбит недавно, пыли нет. В доме всё по-вдовьи аккуратно.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Сервант', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Сервант с фарфоровым чайником и пиалами. Посуда для гостей, стоит ровно, по ранжиру. Давно не доставали.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Папиросы', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Пачки «Беломора» в ряд на подоконнике. Запас на месяц. Хозяин курит много.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фотография', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'На холодильнике фото женщины в чёрной рамке. Покойная жена хозяина. Рамка протёрта.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Грамота', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Школьная грамота дочери: «За отличную учёбу». Зарина, 10 класс. Повешена на самое видное место.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телевизор', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Телевизор под вышитой салфеткой. Выключен, кинескоп в пыли.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Квитанция за свет', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Стопка квитанций за свет на телевизоре. Все оплачены день в день. Аккуратный плательщик.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пальто', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Тёмное пальто на крючке в прихожей. В карманах пусто: ни ключей, ни бумажек.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зеркало', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'Зеркало в прихожей без рамы. Чистое.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Плакат', 'a2371d56-be63-59a7-81d4-f8745d432f5d', 'На двери в комнату дочери плакат эстрадной певицы. Дочери дома нет: отец отправил её к родне в Ташкент.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Магнитофон', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Кассетный магнитофон на тумбочке. Батарейки сели. Рядом стопка кассет с казахской эстрадой.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Аудиокассета', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Кассеты на тумбочке: казахская эстрада, одна подписана от руки «Мама». Обычные.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Банка курта', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Банка курта на тумбочке. Мать прислала из аула. Почти полная.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Плакат', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Плакат с Брюсом Ли над тумбочкой. Края загнуты, держится на пластилине.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Свечи', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Огарки свечей на подоконнике. Свет здесь отключают чаще, чем в центре.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фанера в окне', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Вместо одного стекла фанера. Дует. Так уже вторую зиму.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Игральные карты', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Колода на столе, сдача не доиграна. Соседи играли до ночи.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Пепельница', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Консервная банка с окурками «Примы». Олжас не курит: это соседи.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Полотенце', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Застиранное полотенце на гвозде у двери. Общее.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Кружка', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Эмалированная кружка на столе, на дне чайная гуща.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Одежда соседа', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Ворох одежды на соседней койке. Штаны, свитер. Чужое, к делу не относится.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Коробки', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Три коробки, перевязанные бечёвкой. Маркером: «Köln». Посуда, книги, бельё. Хозяева собирались, да всё не увезли.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Календарь', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Настенный календарь на 1994 год, немецкий, с картинкой: домик в горах. С тех пор его никто не перевернул.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Чайник', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Эмалированный чайник на плите. Сухой внутри, в накипи. Им давно не пользовались.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Умывальник', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Умывальник с бачком, эмаль побита. Бачок пустой, вода давно высохла.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Шкаф', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Платяной шкаф, двери настежь. Полки пустые, только бумага на дне. Вещи увезли в Германию.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Вешалка', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Вешалка у двери, на крючках голые плечики. Пальто хозяева забрали с собой.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Табличка', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'За окном на калитке табличка «Продаётся», написана от руки. Буквы уже выцвели.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Входная дверь', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Входная дверь, обитая дерматином, с пуговицами. Замок цел, следов взлома нет.');

-- 6. Экран обвинения
insert into case_accusation (case_id, required_evidence_ids, organizer_options, correct_organizer_character_id, accomplices, ending_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', array['27ae146a-a05c-5e7a-84a1-899c35e883e4','6fc41a46-a0eb-5890-9b26-3b19bcef490d']::uuid[], '[{"character_id": "5b4c1ece-ba00-50d6-9113-73e03e05ccd8", "label": "Фархад Мамаджанов"}, {"character_id": "ea6167fb-4eea-5e08-ae65-e5fce24e6a6c", "label": "Олжас Бекенов"}, {"character_id": "2d9e7245-2e05-5079-86f1-f9b2edb1f3e9", "label": "Ерлан Нуртазин"}, {"character_id": "a7955352-673d-5ff7-bfcc-506079544d1f", "label": "Данияр Ахметов"}, {"character_id": "96e916c8-7fd0-5edc-a4fe-1a6aeda231bf", "label": "Алия Сартакова (Жумабаева)"}]'::jsonb, '5b4c1ece-ba00-50d6-9113-73e03e05ccd8', '[{"character_id": "ea6167fb-4eea-5e08-ae65-e5fce24e6a6c", "question": "Роль: Олжас Бекенов", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": true}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": false}, {"label": "Не причастен к похищению и убийству", "correct": false}], "required_reaction_evidence_id": "d91852b9-daca-5340-80c9-a13cffe680cc"}, {"character_id": "2d9e7245-2e05-5079-86f1-f9b2edb1f3e9", "question": "Роль: Ерлан Нуртазин", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": false}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": true}, {"label": "Не причастен к похищению и убийству", "correct": false}], "required_reaction_evidence_id": "c50332f2-fb14-5cff-9ea2-9581024ac2e3"}, {"character_id": "a7955352-673d-5ff7-bfcc-506079544d1f", "question": "Роль: Данияр Ахметов", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": false}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": false}, {"label": "Не причастен к похищению и убийству", "correct": true}], "required_reaction_evidence_id": "b170d031-ba6c-5e70-829f-cbd96f761931"}, {"character_id": "96e916c8-7fd0-5edc-a4fe-1a6aeda231bf", "question": "Роль: Алия Сартакова (Жумабаева)", "options": [{"label": "Соучастник похищения, без умысла на убийство", "correct": false}, {"label": "Соучастник похищения и убийства", "correct": false}, {"label": "Пособник-наводчик, о похищении не знал", "correct": false}, {"label": "Не причастен к похищению и убийству", "correct": true}], "required_reaction_evidence_id": "60950128-af31-513e-b8de-bb87b02332cc"}]'::jsonb, 'Фархаду Мамаджанову предъявлено обвинение: похищение человека с целью выкупа и умышленное убийство.
Кашель он больше не прячет. На допросах курит «Беломор», одну за другой. Просит не трогать дочь. Ни о чём не торгуется.
Олжас Бекенов пойдёт по делу соучастником похищения, без умысла на убийство. На каждом допросе он повторяет одно: это он передал дяде слова Игоря. Легче ему не становится.
Ерлан Нуртазин — пособник. О похищении не знал. Но четверги продал. Бывший сержант будет сидеть отдельно от остальных. И он это знает.

Игоря Сартакова хоронят в первую неделю декабря. Идёт снег. В городе опять отключают свет, поминальный стол накрывают при свечах.
Валентина Петровна стоит у могилы прямо. При чужих не плачет. Когда всё кончается, она подходит к вам. За руку держит двенадцатилетнюю Дашу.
— Спасибо, что не поверили.
И уходит. Девочка дважды оглядывается.

Впрочем, это уже совсем другая история.

Из бумаг, найденных в мешке с рисом, Сеитова одну откладывает отдельно. Расписка на бланке купонного инвестиционного фонда.
Данияра Ахметова вызывают опознать бланк. Он долго смотрит на шапку.
— Через этот фонд мы в девяносто пятом приватизировали базу. Без Фархада.
Фархаду показывают ту же бумагу. Впервые за всё следствие он улыбается.
— Я им отдал за долю, которую они у меня забрали. Спроси, дорогой, у кого ещё они её забрали.');

-- 6b. Сцены начальства
insert into phone_calls (id, case_id, caller_character_id, caller_name, caller_role, style, order_index, unlock_condition_key, dialogue_text) values ('6879697e-dfaf-523c-8a4f-a809dea63c0a', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', null, 'Начальник следственного отдела', 'Записка на столе', 'scene', 1, 'any:54bf13bc-3525-5eec-9441-609d8ee21f59', 'На вашем столе, поверх отказного материала, листок из перекидного календаря. Синий карандаш, почерк начальника отдела:

«Читал Кана. Значит, не угар.
Звонил начальник Медеуского РОВД. Обиделся: забираем у них чистый материал. Звонил генералу. Генерал спросил меня, зачем. Я сказал: удушение. Генерал сказал: тогда быстро.
Мать звонила. Спрашивала, когда отдадут Игоря. Я не знал, что ей ответить.
Неделя — это пять рабочих дней. Считай сам».');
insert into phone_calls (id, case_id, caller_character_id, caller_name, caller_role, style, order_index, unlock_condition_key, dialogue_text) values ('470eea08-4225-536c-aca7-5c7f7ac1db01', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', null, 'Начальник следственного отдела', 'Коридор ГУВД, у курилки', 'scene', 2, 'any:0146fe89-1029-5d65-87bb-f750dfe7ad2d', 'Начальник отдела докуривает у окна в конце коридора. На вас не смотрит.
— Бекенов. Деньги из выкупа, в похищении признался сам. Прокурор доволен. Говорит: оформляйте на него, остальное суд разберёт.
(пауза)
— Из министерства звонили. Не про Бекенова. Про то, почему у меня бизнесмена до сих пор не похоронили.
(тушит окурок о подоконник)
— Красиво, да. Я бы и сам подписал. Только меня спросят одно: кто его задушил. И я должен буду ответить. Ты мне скажи — он? Если он, докажи. Если не он — скажи сейчас. Не в пятницу.');
insert into phone_calls (id, case_id, caller_character_id, caller_name, caller_role, style, order_index, unlock_condition_key, dialogue_text) values ('a9349cc1-fa86-51b9-9a9b-009f15f0cbde', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', null, 'Начальник следственного отдела', 'Внутренний телефон', 'scene', 3, 'any:00b31a8e-e1ee-5474-a323-177b43b153d3|2d1a03f4-be7f-5007-8fe1-71c12d498c29', 'Звонит внутренний. Трубка тяжёлая, с трещиной на корпусе.
— Мамаджанов в изоляторе. Семьдесят два часа. Потом либо арест, либо отпускаем.
(слышно, как он прикрывает трубку ладонью: «Да. Понял. Да»)
— Прокуратура хочет обвинение до похорон. Я сказал: будет.
(пауза)
— Он спокойный, говорят. Чай попросил. Такие спокойные на бумагу не ложатся сами. Не подведи меня. И себя.
Короткие гудки.');

-- 7. Тестовая партия для владельца последней покупки (открыть /game/ebd8093a-9023-532f-9b07-87d885dcf31a)
